// src/components/CountdownTimer.js
import React, { useState, useEffect } from "react";

const CountdownTimer = () => {
  // 👉 YAHAN APNI UPCOMING ELECTION DATE SET KARO
  // Jaise: 1 March 2026, 8:00 AM IST (sirf example)
  // Jab ECI official date announce kare, sirf is line me date change karna hai.
  const ELECTION_CONFIG = {
    electionName: "Uttar Pradesh Assembly Elections 2026",
    // ISO format with IST offset (+05:30)
    electionDateTime: "2026-03-01T08:00:00+05:30",
    currentStatus: "Expected Schedule (Not Official)",
    resultDate: "2026-03-31",
    totalPhases: 1,
    phases: [
      {
        phase: "Single Phase",
        date: "2026-03-01",
        states: ["Uttar Pradesh"],
      },
    ],
  };

  const [timeLeft, setTimeLeft] = useState({
    days: 0,
    hours: 0,
    minutes: 0,
    seconds: 0,
  });

  // 🔹 Calculate time left from *now* to ELECTION_CONFIG.electionDateTime
  const calculateTimeLeft = () => {
    const target = new Date(ELECTION_CONFIG.electionDateTime).getTime();
    const now = new Date().getTime();
    let diff = target - now;

    // Agar election date past ho gayi ho → next 5 saal baad approx
    if (diff < 0) {
      const next = new Date(ELECTION_CONFIG.electionDateTime);
      next.setFullYear(next.getFullYear() + 5);
      diff = next.getTime() - now;
    }

    const days = Math.floor(diff / (1000 * 60 * 60 * 24));
    const hours = Math.floor(
      (diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60)
    );
    const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
    const seconds = Math.floor((diff % (1000 * 60)) / 1000);

    return { days, hours, minutes, seconds };
  };

  useEffect(() => {
    // initial calculation
    setTimeLeft(calculateTimeLeft());

    // har second re-calc
    const timer = setInterval(() => {
      setTimeLeft(calculateTimeLeft());
    }, 1000);

    return () => clearInterval(timer);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString("en-IN", {
      weekday: "long",
      year: "numeric",
      month: "long",
      day: "numeric",
    });
  };

  const { electionName, currentStatus, totalPhases, resultDate, phases } =
    ELECTION_CONFIG;

  return (
    <div className="countdown-timer">
      {/* Election info block */}
      <div className="election-info">
        <h3>🗳️ {electionName}</h3>
        <p className="election-date">
          <strong>Polling Day:</strong>{" "}
          {formatDate(ELECTION_CONFIG.electionDateTime)}
        </p>
        <p className="election-status">
          <strong>Status:</strong> {currentStatus}
          {totalPhases && ` • ${totalPhases} Phase(s)`}
        </p>
        {resultDate && (
          <p className="result-date">
            <strong>Expected Results:</strong> {formatDate(resultDate)}
          </p>
        )}
      </div>

      {/* Live countdown numbers */}
      <div className="countdown-grid">
        <div className="countdown-item">
          <div className="countdown-value">{timeLeft.days}</div>
          <div className="countdown-label">Days</div>
        </div>
        <div className="countdown-item">
          <div className="countdown-value">{timeLeft.hours}</div>
          <div className="countdown-label">Hours</div>
        </div>
        <div className="countdown-item">
          <div className="countdown-value">{timeLeft.minutes}</div>
          <div className="countdown-label">Minutes</div>
        </div>
        <div className="countdown-item">
          <div className="countdown-value">{timeLeft.seconds}</div>
          <div className="countdown-label">Seconds</div>
        </div>
      </div>

      {/* Phases info */}
      {phases && phases.length > 0 && (
        <div className="phases-info">
          <h4>Election Phase:</h4>
          <div className="phases-list">
            {phases.slice(0, 3).map((phase, index) => (
              <div key={index} className="phase-item">
                <strong>{phase.phase}:</strong> {formatDate(phase.date)}
                {phase.states && (
                  <span className="phase-states">
                    {" "}
                    - {phase.states.slice(0, 2).join(", ")}
                  </span>
                )}
              </div>
            ))}
          </div>
        </div>
      )}

      <div className="countdown-note">
        <p>
          ⏰ Live countdown to{" "}
          <strong>Uttar Pradesh Assembly Elections 2026</strong>
        </p>
        <p className="last-updated">
          Last updated: {new Date().toLocaleTimeString()}
        </p>
        <p style={{ fontSize: "11px", opacity: 0.8, marginTop: "6px" }}>
          * Dates shown are configured in the app. Please verify final schedule
          on the official Election Commission of India (ECI) website.
        </p>
      </div>
    </div>
  );
};

export default CountdownTimer;
